export default function AboutSection() {
    return (
        <section className="py-24">
            <div
                className="container mx-auto max-w-5xl"
                style={{
                    display: "grid",
                    gridTemplateColumns: "200px 1fr",
                    gap: "4rem",
                    alignItems: "start",
                }}
            >
                <h2
                    className="text-sm font-semibold uppercase text-(--foreground)"
                    style={{ paddingTop: "0.25rem" }}
                >
                    About
                </h2>
                <div className="grid md:grid-cols-2 gap-16 items-start">
                    <img
                        src="https://storage.googleapis.com/banani-avatars/avatar%2Ffemale%2F25-35%2FAfrican%2F1"
                        alt="Portrait"
                        className="w-full h-auto rounded shadow-sm object-cover grayscale contrast-110 bg-(--muted)"
                    />
                    <div className="flex flex-col gap-6">
                        <div className="space-y-4 text-sm text-(--muted-foreground)">
                            <p>
                                Hello! I'm Yemi — a backend-focused full-stack
                                developer, creative technologist, and continuous
                                learner. I specialize in building fast, secure,
                                and functional web systems that behave
                                predictably at scale.
                            </p>
                            <p>
                                Whether it's architecting a startup's first MVP,
                                migrating legacy systems, or designing robust
                                internal APIs, I bring ideas to life using
                                industry-standard tools. My core stack involves
                                Python, Java, TypeScript, and robust databases
                                like PostgreSQL and MongoDB.
                            </p>
                            <p>
                                My approach to problem-solving is deeply rooted
                                in research and iterative refinement. I dig deep
                                into challenges to uncover the best foundational
                                architectures, ensuring what we build today
                                won't break tomorrow.
                            </p>
                        </div>
                        <div className="mt-8 pt-6 border-t border-dashed border-(--border)">
                            <h3 className="text-xs font-semibold uppercase tracking-wider mb-4 text-(--foreground)">
                                Unpaid Compliments
                            </h3>
                            <p className="italic text-lg leading-relaxed mb-2 text-(--foreground)">
                                "Working with Yemi has been transformative. Her
                                ability to take our ideas and turn them into
                                real, functional systems is unmatched."
                            </p>
                            <p className="text-sm text-(--muted-foreground)">
                                — Olubunmi O., Software Tester
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
}
